import {curveModes,validCurveWeights,validCurveTimeHandles,curveControlValue,curveStoredTangent,curveKeyWeight} from './curve-sampling.js';
import {subdivideCurve} from './curve-subdivision.js';
export const sectionWeightModes=curveModes.filter(mode=>mode!=='constant');
export const sectionWeightFields=['arriveTangent','leaveTangent','arriveWeight','leaveWeight','arriveControl','leaveControl'];
export const weightCubic=mode=>!['linear','step','constant',undefined].includes(mode);
export function validWeightCurveGeometry(keys,linearOnly=false){
 if(!keys.every(k=>(k.interpolation===undefined||(linearOnly?['linear','step']:sectionWeightModes).includes(k.interpolation))&&sectionWeightFields.every(f=>k[f]===undefined||!linearOnly&&Number.isFinite(k[f])&&(!f.endsWith('Tangent')||Math.abs(k[f])<=100000))&&validCurveWeights(k,k.value))||!validCurveTimeHandles(keys,'linear'))return false;
 const unit=v=>Number.isFinite(v)&&v>=-1e-10&&v<=1+1e-10;
 for(let i=0;i<keys.length-1;i++)if(weightCubic(keys[i].interpolation)&&(!unit(keys[i].value+curveControlValue(keys,i,0,'leave','linear'))||!unit(keys[i+1].value+curveControlValue(keys,i+1,0,'arrive','linear'))))return false;
 return true;
}
// Freeze implicit slopes before removing neighbours or splitting a segment.
// Unit control hulls make exact subdivision remain a unit-valued weight curve.
export function explicitWeightCurve(keys){return keys.map((k,i)=>{const out={...k};if(weightCubic(k.interpolation)){out.arriveTangent=curveStoredTangent(keys,i,0,'arriveTangent','linear');out.leaveTangent=curveStoredTangent(keys,i,0,'leaveTangent','linear');if(k.interpolation==='clampedAuto')for(const f of ['arriveWeight','leaveWeight','arriveControl','leaveControl'])delete out[f];out.interpolation='break';}return out;});}
export function splitWeightCurve(keys,time){if(keys.every(k=>!weightCubic(k.interpolation))){const result=keys.map(k=>({...k}));if(result.some(k=>k.time===time))return result;let i=0;while(i+1<result.length&&result[i+1].time<time)i++;const a=result[i],b=result[i+1];if(!b||time<a.time||time>b.time)throw Error('가중치 분할 시각을 확인하세요.');const value=a.interpolation==='step'?a.value:a.value+(b.value-a.value)*(time-a.time)/(b.time-a.time);result.splice(i+1,0,{time,value,...a.interpolation?{interpolation:a.interpolation}:{}});return result;}return subdivideCurve({keys:explicitWeightCurve(keys),interpolation:'linear'},[time]).keys;}
export function weightSegmentControls(keys,index){const a=keys[index],b=keys[index+1],duration=b.time-a.time;return{aTime:a.time+duration*(a.interpolation==='clampedAuto'?1/3:curveKeyWeight(a,0,'leaveWeight')),aValue:a.value+curveControlValue(keys,index,0,'leave','linear'),bTime:b.time-duration*(b.interpolation==='clampedAuto'?1/3:curveKeyWeight(b,0,'arriveWeight')),bValue:b.value+curveControlValue(keys,index+1,0,'arrive','linear')};}
export const sectionWeightCubicContract=Object.freeze({field:'section.weightCurve scalar keys retain time/value/linear/step and optionally clampedAuto/auto/user/break with existing arrive/leave Tangent, Weight and Control fields',bounds:'Key values0..1; cubic effective control values must also stay in0..1 (floating-boundary tolerance1e-10), so their convex hull stays unit-valued without arbitrary overshoot clipping. Existing monotone Bezier time-handle validation and scalar tangent/weight bounds apply.',runtime:'Existing scalar Hermite/weighted Bezier time inversion; prepared weak binary key lookup, no per-frame key copy or sort. Audio volumeCurve retains its explicit linear/step-only validator and UI.',authoring:'Typed page32 controls/actual SVG Bezier geometry; edit validates full candidate before replacement. Exact de Casteljau add/front trim freezes implicit tangents before neighbour changes; no automatic key baking.',limits:'No cubic AudioParam scheduling/pitch-preserving time stretch or full independent-channel editing. Implicit auto curves whose control hull exceeds unit range reject; clampedAuto keeps bounded monotone slopes.'});
